class EmirClearingObligationCheckRequest(BaseModel):
    """Request parameters for emir_clearing_obligation_check().

    ``notionals`` covers ALL asset classes the counterparty has positions in,
    not just one -- required for the FC any-class-breach rule (EMIR REFIT
    Art. 4a(1)): a single class's notional alone cannot answer whether an
    FC's clearing obligation extends to its other classes too.
    """

    model_config = ConfigDict(allow_inf_nan=False)

    notionals: dict[str, float] = Field(
        description="Mapping asset_class -> gross notional outstanding for this counterparty, across ALL asset classes it holds positions in. Required (not just the one class being asked about) for the FC any-class-breach rule: a single class's notional alone cannot answer whether the FC-wide obligation applies."
    )
    counterparty_category: str = Field(description='One of "FC", "NFC+", "NFC-".')
    clearing_thresholds: dict[str, float] = Field(
        description="Mapping asset_class -> clearing threshold notional."
    )


class EmirClearingObligationCheckResponse(BaseModel):
    """Result of emir_clearing_obligation_check(). Mirrors the engine return dict."""

    model_config = ConfigDict(extra="allow", protected_namespaces=())

    any_class_breached: Any = Field(default=None)
    clearing_required: Any = Field(default=None)
    counterparty_category: Any = Field(default=None)


